create table if not exists public.timeline_daw_normalization_evidence_notifications(id text primary key,idempotency_key text not null unique,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,incident_id text not null references public.timeline_daw_normalization_evidence_incidents(id) on delete cascade,checkpoint_id text not null references public.timeline_daw_normalization_evidence_checkpoints(id),issue text not null,level integer not null check(level between 1 and 3),severity text not null check(severity in('warning','critical')),title text not null,href text not null,notification_checksum text not null,state text not null default 'queued' check(state in('queued','delivered','retry','dead-letter','acknowledged')),attempt_count integer not null default 0,next_attempt_at timestamptz,last_error text,delivered_at timestamptz,acknowledged_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.timeline_daw_normalization_evidence_notification_attempts(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,notification_id text not null references public.timeline_daw_normalization_evidence_notifications(id) on delete cascade,attempt integer not null,outcome text not null check(outcome in('delivered','retry','dead-letter')),error text,receipt jsonb not null,receipt_checksum text not null,created_at timestamptz not null default now(),unique(notification_id,attempt));
create table if not exists public.timeline_daw_normalization_evidence_notification_runs(id text primary key,started_at timestamptz not null,finished_at timestamptz not null,processed integer not null,delivered integer not null,retried integer not null,dead_lettered integer not null,failures jsonb not null default '[]'::jsonb);
alter table public.timeline_daw_normalization_evidence_notifications enable row level security;alter table public.timeline_daw_normalization_evidence_notification_attempts enable row level security;alter table public.timeline_daw_normalization_evidence_notification_runs enable row level security;
create policy timeline_daw_normalization_evidence_notifications_owner on public.timeline_daw_normalization_evidence_notifications for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy timeline_daw_normalization_evidence_notification_attempts_owner on public.timeline_daw_normalization_evidence_notification_attempts for select to authenticated using(owner_id=auth.uid());
